#@help ___session_switch1
# @command session switch <name>|<PID> [<from>]
# @summary Stop active sessions (all, or only <from>), then resume the target session
# @group   sessions
# @param   name|PID  saved session to switch to
# @param   from      optional: session to stop (default: all active sessions)
# @returns stop + start commands
# @example vpn-switch session switch work
# @example vpn-switch session switch work home
# @see     session start
# @see     session stop
#@end
___session_switch1() {
  local target_id="$1"
  local resolved_pid

  # Validate the target BEFORE emitting any stop: a typo in the target
  # must not take the active sessions down and leave the user offline.
  if ! resolved_pid=$(resolve_session_id "$target_id"); then
    echo "\"\$VPN_SWITCH_CONTEXT_SCRIPT\" error \"Named session not found: $target_id\""
    return
  fi

  local session_dir="$VPN_SWITCH_BASE/.session/$resolved_pid"
  if [ ! -d "$session_dir" ]; then
    echo "\"\$VPN_SWITCH_CONTEXT_SCRIPT\" error \"Stale session link $target_id: $resolved_pid\" \"Session directory removed - run vpn-switch session clean\""
    return
  fi

  # Stop only the sessions that are actually alive, then resume the
  # target. Unlike the no-arg 'session stop' (which iterates every
  # session dir and relies on idempotent disconnects), switch filters
  # via is_session_alive at generation time — the emitted plan then
  # names exactly the sessions that will be torn down, which is what a
  # user inspecting the batch expects to see. Stopping the target
  # itself (if it happens to be the active one) is harmless: its
  # session directory survives a stop (only 'session remove' deletes
  # it), so the subsequent start simply reconnects it.
  local session_base="$VPN_SWITCH_BASE/.session"
  for session_dir in "$session_base"/*/; do
    [ ! -d "$session_dir" ] && continue
    is_session_alive "$session_dir" || continue
    local pid=$(basename -- "$session_dir")
    echo "\"\$VPN_SWITCH_CONTEXT_SCRIPT\" session stop \"$pid\""
  done

  echo "\"\$VPN_SWITCH_CONTEXT_SCRIPT\" session start \"$resolved_pid\""
}

